#!/usr/bin/env bash
set -eoux pipefail

# This script creates and enables a test policy that triggers on file activity events
# The policy will trigger on file access in sensitive directories that are generated by the fake workload

DIR="$( cd "$( dirname "${BASH_SOURCE[0]}" )" && pwd)"

# Create a file activity policy that matches the directories used in fake file activity generation
# These directories are defined in sensor/kubernetes/fake/fileactivity.go:
# /etc/security, /etc/pam.d, /etc/ssh, /var/log, /var/run, /tmp, /etc/kubernetes, /etc/cni, /etc/sysconfig, /etc/audit
POLICY_JSON='{
  "name": "File Activity Test Policy",
  "description": "Test policy for file activity performance testing - triggers on file access in test directories",
  "rationale": "This policy matches file activity in directories used by the fake workload to measure performance impact",
  "remediation": "This is a test policy for performance testing",
  "categories": ["Anomalous Activity"],
  "lifecycleStages": ["RUNTIME"],
  "eventSource": "DEPLOYMENT_EVENT",
  "severity": "LOW_SEVERITY",
  "disabled": false,
  "policySections": [
    {
      "policyGroups": [
        {
          "fieldName": "File Path",
          "values": [
            {
              "value": "/etc/security/.*"
            },
            {
              "value": "/etc/pam.d/.*"
            },
            {
              "value": "/etc/ssh/.*"
            },
            {
              "value": "/var/log/.*"
            },
            {
              "value": "/var/run/.*"
            },
            {
              "value": "/tmp/.*"
            },
            {
              "value": "/etc/kubernetes/.*"
            },
            {
              "value": "/etc/cni/.*"
            },
            {
              "value": "/etc/sysconfig/.*"
            },
            {
              "value": "/etc/audit/.*"
            }
          ]
        }
      ]
    }
  ],
  "mitreAttackVectors": [],
  "isDefault": false
}'

# Post the policy to Central
curl -k -X POST \
  -H "Authorization: Bearer ${ROX_API_TOKEN}" \
  -H "Content-Type: application/json" \
  -d "${POLICY_JSON}" \
  "${ROX_ENDPOINT}/v1/policies" || echo "Policy may already exist or failed to create"

echo "File activity test policy enabled"
